// [입력] $json.Log_Detail 에 전체 로그 텍스트가 들어있음

let raw = $json.Log_Detail || '';

if (typeof raw !== 'string') {
  try {
    raw = JSON.stringify(raw);
  } catch {
    raw = String(raw);
  }
}

let masked = String(raw);

// 민감 PII 및 IP 마스킹 패턴
masked = masked
  // 이메일
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[EMAIL]')
  // 전화번호
  .replace(/\b0\d{1,2}-?\d{3,4}-?\d{4}\b/g, '[PHONE]')
  // 주민등록번호
  .replace(/\b\d{6}[- ]?\d{7}\b/g, '[RRN]')
  // 카드번호
  .replace(/\b(?:\d[ -]*?){13,16}\b/g, '[CARD]')
  // IP 주소
  .replace(/\b\d{1,3}(?:\.\d{1,3}){3}\b/g, '[IP]');

// 대시보드용 짧은 스니펫 (예: 400자 제한)
const MAX_LEN = 400;
let snippet = masked;

if (snippet.length > MAX_LEN) {
  snippet = snippet.slice(0, MAX_LEN) + ' ...[생략됨]';
}

// 정책:
// - 원본은 meta.extra.body.raw_log 에 이미 들어있으니 그대로 두고,
// - 대시보드/백엔드에서는 마스킹된 버전을 사용하도록 별도 필드로 저장.
return {
  ...$json,
  redactedLog: masked,        // 전체 마스킹 버전
  redactedSnippet: snippet    // 잘린 미리보기 버전
};

// [입력] 전 노드에서 온 표준 스키마
//   - $json.Log_Detail 에 전체 로그 텍스트가 들어있음

let text = $json.Log_Detail || '';

if (typeof text !== 'string') {
  try {
    text = JSON.stringify(text);
  } catch {
    text = String(text);
  }
}

text = String(text);

// 공백뿐이면 PII 없음으로 처리
if (!text.trim().length) {
  return {
    ...$json,
    pii_regex_hits: 0,          // 이메일/전화/주민/카드 기준
    pii_regex_types: [],
    pii_regex_found: false,
    pii_regex_summary: '정규식 기준 민감 PII 패턴 미탐지',
    ip_hits: 0,
    ip_found: false
  };
}

// 1) "민감 PII" 패턴들 (학습 금지/경고 기준)
const piiPatterns = {
  EMAIL: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g,
  PHONE: /\b0\d{1,2}-?\d{3,4}-?\d{4}\b/g,          // 휴대폰/전화번호
  RRN: /\b\d{6}[- ]?\d{7}\b/g,                    // 주민번호(6-7)
  CARD: /\b(?:\d[ -]*?){13,16}\b/g                // 카드번호(13~16자리)
};

// 2) IP는 별도 카운트 (민감 PII 판단에는 포함 안 함)
const ipRegex = /\b\d{1,3}(?:\.\d{1,3}){3}\b/g;

const counts = {};
let totalSensitiveHits = 0;

// 민감 PII 패턴 매칭
for (const [type, regex] of Object.entries(piiPatterns)) {
  const matches = text.match(regex);
  const count = matches ? matches.length : 0;
  counts[type] = count;
  totalSensitiveHits += count;
}

// 실제로 하나라도 잡힌 민감 PII 타입만 리스트로
const hitTypes = Object.entries(counts)
  .filter(([, c]) => c > 0)
  .map(([t]) => t);

const piiFound = totalSensitiveHits > 0;

// IP는 별도 계산
const ipMatches = text.match(ipRegex);
const ipCount = ipMatches ? ipMatches.length : 0;
const ipFound = ipCount > 0;

// 사람 눈에 보이는 요약 문자열 생성
let summary = '정규식 기준 민감 PII 패턴 미탐지';

if (piiFound) {
  const parts = [];

  if (counts.EMAIL) parts.push(`이메일 ${counts.EMAIL}건`);
  if (counts.PHONE) parts.push(`전화번호 ${counts.PHONE}건`);
  if (counts.RRN)   parts.push(`주민등록번호 패턴 ${counts.RRN}건`);
  if (counts.CARD)  parts.push(`카드번호 패턴 ${counts.CARD}건`);

  summary = parts.join(', ') + ' 탐지됨 (정규식 기준).';

  if (ipFound) {
    summary += ` IP 주소 ${ipCount}건도 포함되어 있습니다.`;
  }
} else if (ipFound) {
  // 민감 PII는 없고, IP만 있는 케이스
  summary = `민감 PII는 없고, IP 주소 ${ipCount}건만 탐지됨 (정규식 기준).`;
}

// 기존 필드는 그대로 두고, PII/IP 관련 필드만 추가해서 반환
return {
  ...$json,
  pii_regex_hits: totalSensitiveHits,  // 이메일/전화/주민/카드 기준 총합
  pii_regex_types: hitTypes,          // 이메일/전화/주민/카드 중 실제 발견된 타입들
  pii_regex_found: piiFound,          // "민감 PII"가 하나라도 있으면 true
  pii_regex_summary: summary,         // 사람 읽기용 요약
  ip_hits: ipCount,                   // IP 주소 매칭 수
  ip_found: ipFound                   // IP 존재 여부
};

// Webhook로 들어오는 JSON 구조를 최대한 통일해서
// 뒤 노드들이 항상 동일한 필드만 보게 만드는 전처리 노드입니다.

// 1) body 위치 통합 (Postman / 실제 센서 모두 대응)
const body =
  $json.body ||                 // 일반적인 webhook body (테스트 시)
  $json.meta?.extra?.body ||    // n8n 테스트에서 meta.extra.body 로 들어온 경우
  {};

// 2) 원본 로그 문자열 추출
let raw =
  body.raw_log ||
  $json.raw_log ||
  $json.message ||
  $json.log ||
  '';

// 혹시 객체로 온 경우 문자열로 변환
if (raw && typeof raw !== 'string') {
  try {
    raw = JSON.stringify(raw);
  } catch {
    raw = String(raw);
  }
}

// 그래도 비어 있으면 body 전체를 fallback으로 사용
if (!raw || String(raw).trim().length === 0) {
  const fallbackSource = Object.keys(body).length ? body : $json;
  try {
    raw = JSON.stringify(fallbackSource);
  } catch {
    raw = String(fallbackSource);
  }
}

// 3) 공통 필드 정규화 (system / time / IP / user_id 등)

// 🔥 시스템 코드 (내부용 식별자: CHAT_LOG / FILE_SERVER ...)
const systemCode =
  body.system ||
  $json.system ||
  'UNKNOWN';

// 🔥 출처 라벨 (사람이 보는 이름: 메신저/채팅 로그, 파일 서버 등)
let sourceLabel =
  body.source ||        // 랜덤 인시던트 제너레이터에서 넣어주는 한국어 라벨
  $json.source ||       // 다른 시스템에서 이미 내려준 라벨
  systemCode ||         // 그래도 없으면 system 코드라도 사용
  'UNKNOWN';

let time =
  body.time ||
  $json.time ||
  $json.timestamp ||
  new Date().toISOString();   // UTC 기준

// 가능하면 ISO 형식으로 통일 (파싱 실패하면 원본 유지)
try {
  const d = new Date(time);
  if (!isNaN(d.getTime())) {
    time = d.toISOString();
  }
} catch {
  // 그냥 원본 time 사용
}

const clientIp =
  body.client_ip ||
  $json.client_ip ||
  $json.ip ||
  '';

const userId =
  body.user_id ||
  $json.user_id ||
  '';

const userAgent =
  body.user_agent ||
  $json.user_agent ||
  $json.headers?.['user-agent'] ||
  '';

const destIp =
  body.dest_ip ||
  $json.dest_ip ||
  '';

const eventType =
  body.event_type ||
  $json.event_type ||
  body.action ||
  $json.action ||
  '';

// 4) 표준화된 구조로 반환
//    이후 모든 노드는 이 스키마만 신뢰하면 됨.
return {
  // AI / 백엔드 / 대시보드가 함께 쓰는 공통 필드
  Log_Detail: raw,       // 원본 로그 한 줄(또는 한 이벤트, 마스킹 전)
  system: systemCode,    // 내부 코드 (예: CHAT_LOG)
  source: sourceLabel,   // UI용 라벨 (예: 메신저/채팅 로그)
  timestamp: time,       // 발생 시각(UTC ISO 문자열)
  occurred_at: time,     // 나중 단계에서 그대로 써도 되게 한 번 더 복사

  meta: {
    source_ip: clientIp,
    dest_ip: destIp,
    user_id: userId,
    event_type: eventType,
    user_agent: userAgent,

    // extra에는 webhook으로 들어온 전체 원본 JSON을 그대로 보존
    // (디버깅 / 상세 분석용)
    extra: $json
  }
};

// [입력] 이전 노드에서 온 표준 스키마
// - $json.Log_Detail : 전체 로그 텍스트
// - $json.pii_regex_found : 정규식 기준 민감 PII 존재 여부

let text = $json.Log_Detail || '';
if (typeof text !== 'string') {
  try {
    text = JSON.stringify(text);
  } catch {
    text = String(text);
  }
}
text = String(text);

// 민감 PII 여부 (정규식 기준)
const hasSensitivePII = !!$json.pii_regex_found;

// 공격/유출 관련 키워드들 (룰 기반)
const hasErrorWord = /\b(ERROR|ALERT|FAIL|EXCEPTION|CRITICAL|WARN|WARNING)\b/i.test(text);
const hasLeakWord  = /(backup|dump|export|upload|download|ftp|s3|csv|client[_ ]?list|유출|백업|내보내기|메일|gmail|naver\.com|daum\.net)/i.test(text);
const hasAuthWord  = /(login failed|unauthorized|권한 없음|인증 실패|비인가)/i.test(text);

let risk = 'Safe';
let reason = '특별한 이상 징후 없음 (룰 기반).';

// 1) 민감 PII 포함이면 무조건 High
if (hasSensitivePII) {
  risk = 'High';
  reason = '민감 PII(이메일/전화/주민번호/카드번호 등)가 포함된 로그로 판단됨.';
}
// 2) PII는 없지만, 유출/백업 + 에러/경고 키워드 조합
else if (hasLeakWord && (hasErrorWord || hasAuthWord)) {
  risk = 'High';
  reason = '데이터 유출/백업 관련 키워드와 에러/인증 실패가 함께 발견됨.';
}
// 3) PII는 없고, 유출/공격/오류 키워드 단독
else if (hasLeakWord || hasErrorWord || hasAuthWord) {
  risk = 'Medium';
  reason = '데이터 유출/공격/오류 관련 키워드가 포함되어 있음.';
}
// 4) 나머지는 Safe
else {
  risk = 'Safe';
  reason = '알려진 위험 패턴이나 민감 PII가 포함되지 않은 일반 로그.';
}

// 위험도에 따른 대응 추천 (데모용)
let recommendation = '모니터링만 진행 (데모용 기본 추천).';

if (risk === 'High') {
  recommendation = '즉시 보안팀 통보, 관련 계정/시스템 접근 차단 검토.';
} else if (risk === 'Medium') {
  recommendation = '보안 담당자 검토 및 필요 시 규칙/정책 강화.';
} else if (risk === 'Safe') {
  recommendation = '추가 조치 불필요, 일반 로그로 분류.';
}

// 나중에 LLM을 붙여도 interface 맞추기 좋게 필드 이름 설계
const botRisk = risk;  // 이걸 기준으로 뒤에서 학습 여부 결정

return {
  ...$json,
  risk_1st: risk,
  risk_reason_1st: reason,
  recommendation_1st: recommendation,
  botRisk,             // 최종 위험도(현재는 룰 기반)
  bot_risk_final: risk // 나중에 L1+L2 merge 후에도 쓸 수 있게
};

// 학습 대상 여부 계산 Code 노드 (업데이트 버전)

// 1단계 위험도 (룰 기반)
const risk_l1 = $json.botRisk || $json.risk_1st || 'Safe';

// 2단계 위험도 (LLM) – 아직 없으면 null
const risk_l2 = $json.risk_2nd || null;

// 최종 위험도: L2가 있으면 우선 사용
const finalRisk =
  risk_l2 && risk_l2 !== 'Unknown'
    ? risk_l2
    : risk_l1;

// High / Medium 이상이면 "위험한 로그"로 간주
const isRisky =
  finalRisk === 'High' || finalRisk === 'Medium';

// 정규식 / (나중에 LLM PII까지) 기준으로 PII가 없는지
const piiByRegex = !!$json.pii_regex_found;
const piiByLLM1 = !!$json.pii_found_1st;  // 1차 LLM이 PII 찾으면 여기에
const noPII = !piiByRegex && !piiByLLM1;

// 최종 학습 대상 여부
const ai_learn_enabled = isRisky && noPII;

return {
  ...$json,
  final_risk_for_learning: finalRisk,  // 디버깅용
  ai_learn_enabled
};

// n8n → 백엔드로 보낼 최종 JSON 페이로드를 정리하는 노드입니다.

// 백엔드와 동일한 형식의 ID 생성 (없으면 새로 생성)
function makeLogId() {
  const rand = Math.floor(Math.random() * 1000)
    .toString()
    .padStart(3, "0");
  return `LOG-${Date.now()}-${rand}`;
}

const id = $json.id || makeLogId();

// 🔥 최종 위험도 (L2 병합 결과 우선)
const risk =
  $json.bot_risk_final ||
  $json.botRisk ||
  $json.risk_l2 ||
  $json.risk_1st ||
  "Safe";

// 요약: PII 요약 그대로 사용
const piiSummary = $json.pii_regex_summary || "PII 탐지 정보 없음";

// 상세 이유: L2 → L1 → 기존 필드 순서로 우선 사용
const riskReason =
  $json.risk_reason_l2 ||
  $json.risk_reason_l1 ||
  $json.risk_reason_1st ||
  "";

// 추천 대응: L2 → L1 → 기존 필드 순서로 우선 사용
const recommendation =
  $json.recommendation_l2 ||
  $json.recommendation_l1 ||
  $json.recommendation_1st ||
  "";

// 출처(source)
let source =
  $json.source ||
  ($json.body && $json.body.source) ||
  ($json.body && $json.body.system) ||
  $json.system ||
  "UNKNOWN";

const timestamp = $json.timestamp || new Date().toISOString();

// 대시보드에 보여줄 로그 내용은 마스킹된 버전 우선
const logForDisplay = $json.redactedLog || $json.Log_Detail || "(로그 없음)";

// 상태값 (학습 후보 / 일반 로그 등)
let status = "일반 로그";
if ($json.ai_learn_enabled === true) {
  status = "학습 후보";
}
if ($json.ai_learn_completed === true) {
  status = "학습 완료";
}

// 카테고리 (최종 + L1/L2)
const incidentCategoryFinal = $json.incident_category || "monitoring";
const incidentCategoryL1 = $json.incident_category_l1 || incidentCategoryFinal;
const incidentCategoryL2 = $json.incident_category_l2 || incidentCategoryFinal;

// 백엔드로 보낼 페이로드 구성
const backendPayload = {
  id,
  risk,                         // ✅ 최종 위험도
  summary: piiSummary,          // PII 요약
  detail: riskReason,           // 최종 위험도 이유
  recommendation,               // 최종 추천 대응

  // L1 / L2 정보도 같이 보냄 (대시보드/분석용)
  risk_l1: $json.risk_l1 || null,
  risk_l2: $json.risk_l2 || null,
  risk_reason_l1: $json.risk_reason_l1 || null,
  risk_reason_l2: $json.risk_reason_l2 || null,
  recommendation_l1: $json.recommendation_l1 || null,
  recommendation_l2: $json.recommendation_l2 || null,

  action: null,
  source,
  log_detail: logForDisplay,
  timestamp,

  // PII / IP 정보
  pii_regex_found: $json.pii_regex_found || false,
  pii_regex_types: $json.pii_regex_types || [],
  pii_regex_summary: piiSummary,
  ip_found: $json.ip_found || false,
  ip_hits: $json.ip_hits || 0,

  // 학습 상태
  ai_learn_enabled: $json.ai_learn_enabled === true,
  ai_learn_completed: $json.ai_learn_completed === true,
  status,

  // 인시던트 유형
  incident_category: incidentCategoryFinal,
  incident_category_l1: incidentCategoryL1,
  incident_category_l2: incidentCategoryL2,
};

return {
  ...$json,
  id,
  backendPayload,
};

// 🔥 기준 데이터는 "HTTP Payload 준비 Code 노드" 출력으로 고정
const base = $item(0).$node["HTTP Payload 준비 Code 노드"].json;

// 1) 기본 메타 정보
const id = base.id || 'UNKNOWN_ID';

const risk =
  base.bot_risk_final ||
  base.backendPayload?.risk ||
  base.risk_l2 ||
  base.risk_l1 ||
  base.risk_1st ||
  'Unknown';

const source = base.source || base.system || 'UNKNOWN';

const timestamp = base.timestamp || new Date().toISOString();

const piiSummary = base.pii_regex_summary || '민감 PII 미탐지';

const riskReason =
  base.risk_reason_l2 ||
  base.risk_reason_l1 ||
  base.risk_reason_1st ||
  '(위험도 판단 이유 없음)';

const recommendation =
  base.recommendation_l2 ||
  base.recommendation_l1 ||
  base.recommendation_1st ||
  '(추천 대응 없음)';

const srcIp = base.meta?.source_ip || '';
const userId = base.meta?.user_id || '';

const redactedLog =
  base.redactedLog ||
  base.backendPayload?.log_detail ||
  base.log_detail ||
  base.Log_Detail ||
  '(로그 없음)';

// 2) 인시던트 카테고리
const incidentCategory =
  base.incident_category ||
  base.incident_category_l2 ||
  base.incident_category_l1 ||
  base.backendPayload?.incident_category ||
  'monitoring';

// 3) 실제 KB에 저장될 학습용 텍스트
const learnText = `[보안 인시던트 학습용 데이터]

■ 위험도: ${risk}
■ 로그 출처: ${source}
■ 발생 시각: ${timestamp}
■ 소스 IP: ${srcIp}
■ 사용자/계정: ${userId}

■ 로그 내용 (민감정보 마스킹됨):
${redactedLog}

■ PII 탐지 요약:
${piiSummary}

■ 위험도 판단 이유:
${riskReason}

■ 추천 대응:
${recommendation}
`;

// 4) KB API로 보낼 payload
const kbPayload = {
  source: "SecurityFlow",
  category: incidentCategory,
  risk,
  text: learnText,
  meta: {
    log_id: id,
    source,
    timestamp,
    src_ip: srcIp,
    user_id: userId,
    pii_regex_found: base.pii_regex_found || false,
    pii_regex_types: base.pii_regex_types || [],
    incident_category: incidentCategory,
  },
};

return {
  ...base,
  learnText,
  kbPayload,
};

// KB에 정상 반영된 후 호출된다고 가정
// 백엔드 /api/logs/:id 로 PUT 날릴 페이로드 생성

// 1) 우선 현재 아이템에서 시도
let id =
  $json.id ||
  ($json.backendPayload && $json.backendPayload.id);

// 2) 그래도 없으면, "HTTP Payload 준비 Code 노드"의 출력에서 가져오기
if (!id) {
  const fromPayload = $item(0).$node["HTTP Payload 준비 Code 노드"].json;
  id =
    fromPayload.id ||
    (fromPayload.backendPayload && fromPayload.backendPayload.id);
}

if (!id) {
  throw new Error('log id가 없습니다. (HTTP Payload 준비 Code 노드 이름이 정확한지 확인하세요)');
}

const updatePayload = {
  ai_learn_completed: true,
  status: '학습 완료'
};

return {
  ...$json,
  id,
  updatePayload,
  updateUrl: `http://127.0.0.1:3001/api/logs/${id}`
};

// 로그 텍스트 가져오기 (마스킹 전/후 아무거나 있으면 사용)
let text = $json.Log_Detail || '';
if (typeof text !== 'string') {
  try {
    text = JSON.stringify(text);
  } catch {
    text = String(text);
  }
}
text = text.toLowerCase();

// 기본값
let category = 'monitoring'; // 그냥 모니터링/일반 로그

// 데이터 유출/외부 전송 쪽
if (/(backup|export|csv|sftp|ftp|download|upload|client[_ ]?list|csv 파일|백업 파일|내보내기|export)/i.test(text)) {
  category = 'exfiltration';
}
// 계정 탈취/인증 관련
else if (/(login failed|로그인 실패|password|brute force|mfa|2fa|unauthorized|권한 없음|비인가|인증 실패)/i.test(text)) {
  category = 'credential_abuse';
}
// 잘못된 공개 설정(퍼블릭 링크 등)
else if (/(public link|퍼블릭 링크|anyone with the link|전체공개|no auth)/i.test(text)) {
  category = 'misconfiguration';
}

return {
  ...$json,
  incident_category: category
};

