// ⚙️ LLM 결과 머지 Code 노드
// - 현재 $json에는 LLM 노드의 출력만 들어있음: { text: "```json ... ```" }
// - 이전 단계 전체 필드는 $item(0).$node["원본 로그 마스킹 및 삭제1"].json 에서 가져온다.

const base = $item(0).$node["원본 로그 마스킹 및 삭제1"].json;

// 1) LLM text 꺼내기
let raw = $json.text || "";
if (typeof raw !== "string") {
  raw = String(raw);
}

// 2) ```json, ``` 같은 코드 블록 마커 제거
raw = raw
  .replace(/```json/i, "")
  .replace(/```/g, "")
  .trim();

// 3) JSON 파싱
let llm = {};
try {
  llm = JSON.parse(raw);
} catch (e) {
  llm = {};
}

// 4) L1 / L2 위험도 및 카테고리 계산

// L1 = 룰 기반(기존) 위험도
const riskL1 = base.botRisk || base.risk_1st || "Safe";
// L2 = LLM이 내려준 위험도 (없으면 L1 그대로)
const riskL2 = llm.risk || riskL1;

// 위험도 우선순위 매핑
const level = { Safe: 0, Medium: 1, High: 2 };

// 최종 위험도 = 더 높은 레벨 우선
let finalRisk = "Safe";
if (level[riskL1] >= level[riskL2]) {
  finalRisk = riskL1;
} else {
  finalRisk = riskL2;
}

// 카테고리(L1 = 기본, L2 = LLM)
const categoryL1 = base.incident_category || "monitoring";
const categoryL2 = llm.category || categoryL1;
const finalCategory = categoryL2;

// 5) 위험도/PII 기반 학습 가능 여부 자동 계산
const piiByRegex = !!base.pii_regex_found;
const piiByLLM = !!base.pii_found_1st;
const noPII = !piiByRegex && !piiByLLM;
const isRisky = finalRisk === "High" || finalRisk === "Medium";
const ai_learn_enabled = isRisky && noPII;

// 학습 완료 여부(기존 값 유지)
const ai_learn_completed = base.ai_learn_completed || false;

// 6) 합쳐서 반환
return {
  ...base,

  // L1 / L2 세부 정보 저장
  risk_l1: riskL1,
  risk_l2: riskL2,
  risk_reason_l1: base.risk_reason_1st || null,
  risk_reason_l2: llm.reason || null,
  recommendation_l1: base.recommendation_1st || null,
  recommendation_l2: llm.recommendation || null,
  incident_category_l1: categoryL1,
  incident_category_l2: categoryL2,

  // 최종 결과
  bot_risk_final: finalRisk,
  incident_category: finalCategory,

  // 학습 관련
  ai_learn_enabled,
  ai_learn_completed,
};

const base = $item(0).$node["원본 로그 마스킹 및 삭제1"].json;

// HTTP Request 결과(body)가 배열이면 그대로 사용, 아니면 빈 배열
const body = $json.body;
const examples = Array.isArray(body) ? body : [];

// LLM 프롬프트에 바로 넣을 수 있는 텍스트로 변환
const examplesText = examples.length
  ? examples
      .map((e, idx) => {
        const risk = e.risk || 'Unknown';
        const cat = e.meta?.incident_category || 'unknown';
        return `[예시 ${idx + 1}] (위험도: ${risk}, 유형: ${cat})\n${e.text}`;
      })
      .join('\n\n---\n\n')
  : '현재 이 카테고리에 대한 학습 사례가 없습니다. 일반적인 보안 관제 기준으로만 판단하세요.';

return {
  ...base,
  kb_examples: examples,
  kb_examples_text: examplesText,   // 🔹 이걸 LLM 프롬프트에서 쓸 거야
};
